import json, math
from fractions import Fraction

def require(cond, msg):
    if not cond:
        raise RuntimeError("FAIL: " + msg)

def _no_floats(x, path="$"):
    if isinstance(x, float):
        require(not (math.isnan(x) or math.isinf(x)),
                "float literal at " + path)  # reject at parse
    if isinstance(x, dict):
        for k, v in x.items():
            _no_floats(v, path + "." + str(k))
    if isinstance(x, list):
        for i, v in enumerate(x):
            _no_floats(v, path + "[%d]" % i)

def load_witness(text):
    # reject JSON float literals before they ever become Python floats
    for tok in ("NaN", "Infinity", "-Infinity"):
        require(tok not in text, "non-finite literal " + tok)
    import re
    require(not re.search(r'(?<![\w."])\d+\.\d', text),
            "float literal in witness JSON")
    w = json.loads(text)
    _no_floats(w)
    return w

def verify(w):
    require(isinstance(w, dict), "witness not object")
    require(w.get("schema") == "r006-L1-dk-witness-v1", "wrong schema")
    ks = w["ks"]
    U, S = w["U"], w["S"]          # each: {k: sorted list of ints}
    E = w["E"]                     # each: {k: sorted list of ints}
    require(set(U) == set(S) == set(E), "key mismatch across U/S/E")
    # anchor equalities k <= 3: D_k must equal its recorded exact anchor
    anchors = w.get("anchors", {})
    for k in ks:
        Uk, Sk, Ek = U[k], S[k], E[k]
        require(all(isinstance(x, int) for x in Uk+Sk+Ek), "non-int member")
        # domain validity: partition of U, disjoint
        require(len(Sk) + len(Ek) == len(Uk), "conservation |S|+|E|=|U| k=%s" % k)
        require(len(set(Sk) & set(Ek)) == 0, "S,E overlap k=%s" % k)
        # independent complement recount (not reusing S to build E)
        require(set(Sk) | set(Ek) == set(Uk), "complement recount k=%s" % k)
        Dk = Fraction(len(Sk), len(Uk))
        require(Dk >= 0 and Dk <= 1, "D_k out of range k=%s" % k)
        if int(k) <= 3:
            require(str(k) in anchors, "missing anchor k=%s" % k)
            require(Fraction(anchors[str(k)]) == Dk,
                    "anchor equality fails k=%s" % k)
    print("PASS")

if __name__ == "__main__":
    import sys
    verify(load_witness(open(sys.argv[1]).read()))
